parameters.jsCode:
const body = $json.body || $json;

const deptMap = {
  'maintenance': 'facilities@hitam.org',
  'hostel': 'hostel@hitam.org',
  'it_network': 'itsupport@hitam.org',
  'academics': 'academics@hitam.org',
  'event_proposal': 'ssg@hitam.org'
};

const coordinatorEmail = deptMap[body.category] || 'facilities@hitam.org';

return {
  trackingId: body.tracking_id,
  studentName: body.student_name,
  studentEmail: body.student_email,
  coordinatorEmail,
  title: body.title,
  department: body.assigned_department,
  urgency: body.urgency,
  location: body.location
};

